package mx.com.mesaregia.inventario.api.controller;
import mx.com.mesaregia.inventario.application.service.MovimientoInventarioQueryService; import mx.com.mesaregia.inventario.api.response.*; import mx.com.mesaregia.inventario.domain.enums.TipoMovimiento; import org.springframework.data.domain.*; import org.springframework.format.annotation.DateTimeFormat; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.time.LocalDateTime;
import org.springframework.data.web.PageableDefault;
@RestController @RequestMapping("/api/v1/inventario/movimientos") public class MovimientoController {private final MovimientoInventarioQueryService s;public MovimientoController(MovimientoInventarioQueryService s){this.s=s;}@GetMapping@PreAuthorize("hasAuthority('inventario.movimientos.consultar')")public PageResponse<MovimientoResponse> get(@RequestParam(required=false)Long idProducto,@RequestParam(required=false)Long idOrden,@RequestParam(required=false)TipoMovimiento tipo,@RequestParam(required=false)@DateTimeFormat(iso=DateTimeFormat.ISO.DATE_TIME)LocalDateTime desde,@RequestParam(required=false)@DateTimeFormat(iso=DateTimeFormat.ISO.DATE_TIME)LocalDateTime hasta,@PageableDefault(size=20,sort="fechaHora",direction=Sort.Direction.DESC)Pageable p){return s.buscar(idProducto,idOrden,tipo,desde,hasta,p);} }
